INSERT INTO public.notification_template (template_code, channel, target, title, body) VALUES
  ('TECH_MEMO_ASSIGNED', 'PUSH', 'TECHNICIAN', '지정 메모 도착', E'#{기사명} 기사님, 새 메모가 도착했습니다.\n#{메모}\n캘린더 > 메모에서 확인해 주세요.'),
  ('APPLICANT_ACCEPTED', 'ALIMTALK', 'TECHNICIAN', '기사 지원 합격 안내', E'#{기사명}님, 기사 지원에 합격하셨습니다.\n교육 일정은 거점에서 따로 안내드립니다.\n기사 앱은 이 휴대폰 번호의 인증번호로 로그인할 수 있어요.\n문의: #{거점전화}'),
  ('TRAINING_PASSED', 'PUSH', 'TECHNICIAN', '교육 수료', E'#{과정명} 과정을 수료했습니다.\n수료증 번호: #{수료증번호}\n더보기 > 내 교육·등급에서 확인해 주세요.')
ON CONFLICT (template_code) DO NOTHING;
